WhatsAppCapture.InsertStatusEventAndReconcile:
INSERT INTO public.whatsapp_status_events (wamid, status, error_code, recipient, event_ts)
VALUES (@Wamid, @Status, @ErrorCode, @Recipient, to_timestamp(@EventTs::double precision))
ON CONFLICT (wamid, status) DO NOTHING;

SELECT public.fn_reconcile_whatsapp_status();

CategorySummary.DispatchProduction:
SELECT
    COUNT(*) AS total_records,
    COUNT(*) FILTER (WHERE COALESCE(day_overdue, 0) > 0) AS overdue_count,
    COUNT(*) FILTER (WHERE last_reminder_sent::date = CURRENT_DATE) AS reminders_today
FROM {ViewName}
{UserFilter}

Finance.AgingBuckets:
SELECT {BucketCase} AS bucket, MIN(day_overdue) AS sort_key, COUNT(*) AS count,
       COALESCE(SUM(outstanding_amountcal::numeric), 0) AS amount
FROM {ViewName}
WHERE COALESCE(day_overdue, 0) > 0 {WhereAnd}
GROUP BY 1
ORDER BY sort_key

Finance.StatusBreakdown:
SELECT COALESCE(payment_status, 'unknown') AS status, COUNT(*) AS count
FROM {ViewName}
{WhereOnly}
GROUP BY payment_status
ORDER BY count DESC

Finance.RecentlyResolved:
SELECT invoice_number AS reference, client_name AS name, payment_date AS resolved_at
FROM {ViewName}
WHERE payment_status = 'paid' AND payment_date IS NOT NULL {WhereAnd}
ORDER BY payment_date DESC
LIMIT 5

